# clevin-b: MAUVE-42
"""Money helpers.

``Money`` is the Decimal-based value type for every monetary amount in this
package. Amounts are always quantized to two decimal places using
ROUND_HALF_UP as soon as a ``Money`` instance is constructed, so arithmetic
performed through ``Money`` can never drift away from the two-decimal-place
invariant the contract tests rely on.
"""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal, ROUND_HALF_UP

TWO_PLACES = Decimal("0.01")


def quantize(value: Decimal) -> Decimal:
    """Round a Decimal to two places using ROUND_HALF_UP."""
    if not isinstance(value, Decimal):
        raise TypeError("quantize() requires a Decimal")
    return value.quantize(TWO_PLACES, rounding=ROUND_HALF_UP)


@dataclass(frozen=True)
class Money:
    amount: Decimal
    currency: str = "USD"

    def __post_init__(self) -> None:
        if not isinstance(self.amount, Decimal):
            raise TypeError("Money.amount must be a Decimal")
        object.__setattr__(self, "amount", quantize(self.amount))

    def __add__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(self.amount + other.amount, self.currency)

    def __sub__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(self.amount - other.amount, self.currency)

    def __mul__(self, factor: Decimal | int) -> "Money":
        if isinstance(factor, float):
            raise TypeError("Money cannot be multiplied by a float")
        if not isinstance(factor, Decimal):
            factor = Decimal(factor)
        return Money(self.amount * factor, self.currency)

    __rmul__ = __mul__

    def _check(self, other: "Money") -> None:
        if other.currency != self.currency:
            raise ValueError(f"currency mismatch: {self.currency} vs {other.currency}")

    def to_float(self) -> float:
        """Escape hatch for legacy callers that still expect a plain float."""
        return float(self.amount)

    def __str__(self) -> str:
        return f"{self.amount} {self.currency}"

